import { FlaskConical, Sparkles, WalletCards } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

/** Small pill marking simulated delivery metrics. */
export function SimulatedBadge({ className, label = "Simulated" }: { className?: string; label?: string }) {
  return (
    <Badge variant="warning" className={className} title="These numbers are simulated for demo purposes and do not represent live TV delivery.">
      <FlaskConical className="size-3" aria-hidden />
      {label}
    </Badge>
  );
}

/** Pill marking AI output generated by the mock provider. */
export function MockBadge({ className, label = "Mock-generated" }: { className?: string; label?: string }) {
  return (
    <Badge variant="warning" className={className} title="Generated by a mock provider, not a production AI model.">
      <Sparkles className="size-3" aria-hidden />
      {label}
    </Badge>
  );
}

export function MockPaymentBadge({ className }: { className?: string }) {
  return (
    <Badge variant="warning" className={className} title="Mock checkout — no real money is charged.">
      <WalletCards className="size-3" aria-hidden />
      Mock checkout
    </Badge>
  );
}

/** Full-width notice used on pages that show simulated metrics. */
export function SimulatedNotice({ className }: { className?: string }) {
  return (
    <div
      role="note"
      className={cn(
        "flex items-start gap-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900",
        className,
      )}
    >
      <FlaskConical className="mt-0.5 size-4 shrink-0" aria-hidden />
      <p>
        <span className="font-semibold">Simulated metrics.</span> The numbers on this page are generated for demo
        purposes. They are not measurements from live TV delivery.
      </p>
    </div>
  );
}
